.venv/Scripts/python.exe - <<'EOF'
import json, re, sys
sys.path.insert(0, "hindsight")
from record import private_patterns
pats = [re.compile(p, re.I) for p in private_patterns(".")]
line = open(".hindsight/events/d0ed6f64-d887-4315-9fad-95816fbac37f.jsonl", encoding="utf-8").read().splitlines()[41]
env = json.loads(line)
def walk(obj, path=""):
    if isinstance(obj, dict):
        for k, v in obj.items(): walk(v, path + "." + k)
    elif isinstance(obj, str):
        for i, p in enumerate(pats):
            if p.search(obj): print("field", path, "matches pattern #%d" % i, "event", env["event"], env["data"].get("tool"))
walk(env)
EOF

